// Valid Parentheses matching using Stack
var stack = AnimatedStack<String>()
let parens = ["(", "[", "]", ")"]

func isValid(_ sequence: [String], s: inout AnimatedStack<String>) -> Bool {
    for ch in sequence {
        if ch == "(" || ch == "{" || ch == "[" {
            if ch == "(" { s.push(")") }
            if ch == "{" { s.push("}") }
            if ch == "[" { s.push("]") }
        } else {
            if s.isEmpty || s.pop() != ch {
                return false
            }
        }
    }
    return s.isEmpty
}

let result = isValid(parens, s: &stack)
